import{_ as i,C as a,c as d,o as n,aa as p,G as t}from"./chunks/framework.Cn7WEiMX.js";const k=JSON.parse('{"title":"网页界面登录支持及权限","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/web-setup/web-ui-login-support-and-permissions.md","filePath":"wiki/Dynmap/setup/web-setup/web-ui-login-support-and-permissions.md"}'),r={name:"wiki/Dynmap/setup/web-setup/web-ui-login-support-and-permissions.md"};function l(c,e,h,u,m,b){const o=a("NolebaseGitContributors"),s=a("NolebaseGitChangelog");return n(),d("div",null,[e[0]||(e[0]=p('<h1 id="网页界面登录支持及权限" tabindex="-1">网页界面登录支持及权限 <a class="header-anchor" href="#网页界面登录支持及权限" aria-label="Permalink to &quot;网页界面登录支持及权限&quot;">​</a></h1> <p>Dynmap 提供了登录后可见网页界面的选择。在 <code>configuration.txt</code> 中启用如下设置即可使用登录功能：</p> <div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">login-enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>启用后，即可注册玩家账户。账号注册既可在游戏内进行（通过 <code>/dynmap webregister</code> 命令），需要持有 <code>dynmap.webregister</code> 权限。另外，管理员也可以通过命令 <code>/dynmap webregister &lt;玩家名称&gt;</code> 为玩家注册账号（需要 <code>dynmap.webregister.other</code> 权限）。不论哪种注册方式，用户都会持有一段密码，之后可以在网页登录界面新建账号。</p> <p>设置后，网页用户账户会使用对应游戏内玩家的权限，决定网页界面的显示内容。</p> <p>若需要，网页界面还可以限制为仅登录后可见。只需打开这个设置：</p> <div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">login-required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>否则，访客也可以浏览服务器地图——但只能浏览无保护的内容。</p> <h2 id="网页界面限制选项" tabindex="-1">网页界面限制选项 <a class="header-anchor" href="#网页界面限制选项" aria-label="Permalink to &quot;网页界面限制选项&quot;">​</a></h2> <h3 id="世界保护" tabindex="-1">世界保护 <a class="header-anchor" href="#世界保护" aria-label="Permalink to &quot;世界保护&quot;">​</a></h3> <p>若管理员需要限制指定世界的所有地图数据，那么可以在 <code>worlds.txt</code> 中设置 <code>protected</code> 属性（或者通过命令 <code>/dmap worldset &lt;世界名称&gt; protected:true</code> 设置）。完成后，只有拥有 <code>dynmap.world.&lt;世界名称&gt;</code> 权限且登录的玩家才可以看见当前世界。</p> <h3 id="地图保护" tabindex="-1">地图保护 <a class="header-anchor" href="#地图保护" aria-label="Permalink to &quot;地图保护&quot;">​</a></h3> <p>若管理员需要限制指定世界的特定地图数据，那么可以在 <code>worlds.txt</code> 对应地图中设置 <code>protected</code> 属性（或者通过命令 <code>/dmap worldset &lt;世界名称&gt;:&lt;地图名称&gt; protected:true</code> 设置）。完成后，只有拥有 <code>dynmap.world.&lt;世界名称&gt;.&lt;地图名称&gt;</code> 权限且登录的玩家才可以看见当前世界的指定地图。</p> <p>注意：如果地图和世界本身都存在保护状态，玩家需要同时拥有两个权限才可浏览。</p> <h3 id="聊天保护" tabindex="-1">聊天保护 <a class="header-anchor" href="#聊天保护" aria-label="Permalink to &quot;聊天保护&quot;">​</a></h3> <p>若管理员需要限制网页界面浏览聊天栏，那么可以在 <code>ClientUpdateComponent</code> 的 <code>webchat-permissions</code> 处进行设置。打开后，只有拥有 <code>dynmap.webchat</code> 权限且登录的玩家才可以从网页界面发送消息。</p> <h3 id="玩家位置及信息" tabindex="-1">玩家位置及信息 <a class="header-anchor" href="#玩家位置及信息" aria-label="Permalink to &quot;玩家位置及信息&quot;">​</a></h3> <p>若管理员需要限制玩家位置及状态的显示，那么可以在 <code>ClientUpdateComponent</code> 的 <code>protected-player-info</code> 处进行设置。打开后，只有拥有 <code>dynmap.playermarkers.seeall</code> 权限且登录的玩家才可以看到所有可见玩家的位置和/或生命值信息。无对应权限的已登录玩家只能看到自己，访客则完全无法看见玩家。</p> ',34)),t(o),t(s)])}const _=i(r,[["render",l]]);export{k as __pageData,_ as default};
